function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 200) return 'grid needs 1 to 200 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 200) return 'grid needs 1 to 200 columns.';
  if (grid.some(row => !Array.isArray(row) || row.length !== n)) return 'Every row must have the same length.';
  let ones = 0;
  for (const row of grid) for (const v of row) {
    if (v !== 0 && v !== 1) return 'Each cell is 0 or 1.';
    ones += v;
  }
  if (ones < 1 || ones > 6000) return 'The grid needs between 1 and 6000 ones.';
  return null;
}

