  let count = 0;
  for (let r1 = 0; r1 < m; r1++)
    for (let r2 = r1 + 1; r2 < m; r2++)
      for (let c1 = 0; c1 < n; c1++)
        for (let c2 = c1 + 1; c2 < n; c2++)
          if (grid[r1][c1] && grid[r1][c2] && grid[r2][c1] && grid[r2][c2]) count++;
