function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  for (;;) {
    const m = size === 'large' ? int(80, 100) : int(1, 6);
    const n = size === 'large' ? int(80, 100) : int(1, 6);
    const density = size === 'large' ? 0.25 + rand() * 0.33 : 0.2 + rand() * 0.8;
    const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
    // The grid must hold between 1 and 6000 ones.
    const ones = grid.reduce((sum, row) => sum + row.reduce((a, b) => a + b, 0), 0);
    if (ones >= 1 && ones <= 6000) return [grid];
  }
}
